 * Keyed-children diffing, virtual-DOM style, as pure data.
 *
 * `diffChildren(oldKeys, newKeys)` returns a minimal operation list that,
 * when applied left-to-right to `oldKeys`, yields exactly `newKeys`:
 *
 *   - { type: 'remove', key }
 *   - { type: 'insert', key, beforeKey }   // insert before beforeKey, or push at end if null
 *   - { type: 'move',   key, beforeKey }   // move existing key before beforeKey, or to end if null
 *
 * Strategy (as in Vue 3 / Inferno): drop removed keys, then compute a
 * longest-increasing-subsequence over the old indices of the surviving keys
 * *in new order*. Keys on the LIS keep their relative position (zero ops);
 * only out-of-place keys get `move` ops, and brand-new keys get `insert`
 * ops. Ops are emitted right-to-left with an anchor so each op's
 * `beforeKey` is already settled at apply time.
 */

function assertDuplicateFree(keys, label) {
  const seen = new Set();
  for (const key of keys) {
    if (seen.has(key)) {
      throw new TypeError(
        `${label} contains duplicate key ${String(key)}: keyed diffing requires duplicate-free keys`
      );
    }
    seen.add(key);
  }
}

/**
 * Longest strictly increasing subsequence of `seq` (numbers).
 * Returns a Set of the elements belonging to one LIS (O(n log n), patience).
 */
function lisMembers(seq) {
  const n = seq.length;
  const tails = []; // tails[i] = index into seq of smallest tail of an IS of length i+1
  const prev = new Array(n).fill(-1);
  for (let i = 0; i < n; i++) {
    const x = seq[i];
    // binary search: first tail whose value >= x (strict increase)
    let lo = 0;
    let hi = tails.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (seq[tails[mid]] < x) lo = mid + 1;
      else hi = mid;
    }
    if (lo > 0) prev[i] = tails[lo - 1];
    tails[lo] = i;
  }
  const members = new Set();
  for (let i = tails.length ? tails[tails.length - 1] : -1; i !== -1; i = prev[i]) {
    members.add(seq[i]);
  }
  return members;
}

export function diffChildren(oldKeys, newKeys) {
  assertDuplicateFree(oldKeys, 'oldKeys');
  assertDuplicateFree(newKeys, 'newKeys');

  const oldPos = new Map(oldKeys.map((key, index) => [key, index]));

  // 1) Removals: keys present in old but not in new.
  const newSet = new Set(newKeys);
  const ops = [];
  for (const key of oldKeys) {
    if (!newSet.has(key)) ops.push({ type: 'remove', key });
  }

  // Surviving old keys, in their current relative order.
  const surviving = oldKeys.filter((key) => newSet.has(key));

  // 2) LIS over old indices of matched keys, taken in NEW order.
  //    Members of the LIS are already in correct relative order -> no move.
  const seq = [];
  for (const key of newKeys) {
    const pos = oldPos.get(key);
    if (pos !== undefined) seq.push(pos);
  }
  const stable = lisMembers(seq);

  // 3) Right-to-left anchored pass: place every non-stable key immediately
  //    before its successor in newKeys. Stable keys are never touched; any
  //    keys still sitting between them and the anchor belong earlier in
  //    newKeys and will be moved away by later iterations.
  let anchor = null;
  for (let i = newKeys.length - 1; i >= 0; i--) {
    const key = newKeys[i];
    const pos = oldPos.get(key);
    if (pos === undefined) {
      ops.push({ type: 'insert', key, beforeKey: anchor });
    } else if (!stable.has(pos)) {
      ops.push({ type: 'move', key, beforeKey: anchor });
    }
    anchor = key;
  }

  return ops;
}

/** Apply an op list produced by diffChildren to an array of keys. */
export function applyOps(keys, ops) {
  const out = [...keys];
  for (const op of ops) {
    if (op.type === 'remove') {
      const at = out.indexOf(op.key);
      if (at === -1) throw new Error(`applyOps: cannot remove missing key ${String(op.key)}`);
      out.splice(at, 1);
    } else if (op.type === 'insert' || op.type === 'move') {
      if (op.type === 'move') {
        const at = out.indexOf(op.key);
        if (at === -1) throw new Error(`applyOps: cannot move missing key ${String(op.key)}`);
        out.splice(at, 1);
      }
      const at = op.beforeKey === null ? out.length : out.indexOf(op.beforeKey);
      if (op.beforeKey !== null && at === -1) {
        throw new Error(`applyOps: anchor key ${String(op.beforeKey)} not found`);
      }
      out.splice(at, 0, op.key);
    } else {
      throw new Error(`applyOps: unknown op type ${String(op.type)}`);
    }
  }
  return out;
}
