import { diffChildren, applyOps } from '../src/diff.js';

// Deterministic PRNG so the property loop is reproducible.
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function shuffle(rand, arr) {
  const out = [...arr];
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}

const roundTrips = (oldKeys, newKeys) =>
  expect(applyOps(oldKeys, diffChildren(oldKeys, newKeys))).toEqual(newKeys);

describe('diffChildren', () => {
  it('returns an empty op list for identical children', () => {
    expect(diffChildren(['a', 'b', 'c'], ['a', 'b', 'c'])).toEqual([]);
  });

  it('handles empty inputs', () => {
    roundTrips([], []);
    roundTrips([], ['x', 'y']);
    roundTrips(['x', 'y'], []);
  });

  it('full reversal needs at most n-1 moves', () => {
    for (const n of [2, 3, 5, 8, 16]) {
      const keys = Array.from({ length: n }, (_, i) => `k${i}`);
      const ops = diffChildren(keys, [...keys].reverse());
      const moves = ops.filter((op) => op.type === 'move').length;
      expect(moves).toBeLessThanOrEqual(n - 1);
      roundTrips(keys, [...keys].reverse());
    }
  });

  it('pure insertions produce zero move ops', () => {
    const rand = mulberry32(0xc0ffee);
    for (let trial = 0; trial < 300; trial++) {
      const baseSize = 1 + Math.floor(rand() * 10);
      const oldKeys = shuffle(
        rand,
        Array.from({ length: baseSize }, (_, i) => `o${i}`)
      );
      const insertCount = Math.floor(rand() * 6);
      const newKeys = [...oldKeys];
      for (let k = 0; k < insertCount; k++) {
        newKeys.splice(Math.floor(rand() * (newKeys.length + 1)), 0, `n${trial}_${k}`);
      }
      const ops = diffChildren(oldKeys, newKeys);
      expect(ops.every((op) => op.type !== 'move')).toBe(true);
      roundTrips(oldKeys, newKeys);
    }
  });

  it('pure removals produce zero move ops', () => {
    const rand = mulberry32(0xbeef);
    for (let trial = 0; trial < 300; trial++) {
      const oldSize = 2 + Math.floor(rand() * 12);
      const oldKeys = shuffle(
        rand,
        Array.from({ length: oldSize }, (_, i) => `o${i}`)
      );
      const removeCount = Math.floor(rand() * oldSize);
      const newKeys = shuffle(rand, oldKeys).slice(removeCount);
      // keep relative order of the survivors as in oldKeys
      const keep = new Set(newKeys);
      const ordered = oldKeys.filter((key) => keep.has(key));
      const ops = diffChildren(oldKeys, ordered);
      expect(ops.every((op) => op.type !== 'move')).toBe(true);
      roundTrips(oldKeys, ordered);
    }
  });

  it('property loop: random permutations + insert/remove mixes round-trip', () => {
    const rand = mulberry32(1234567);
    let nextKey = 0;
    for (let trial = 0; trial < 300; trial++) {
      const oldSize = Math.floor(rand() * 12);
      const oldKeys = shuffle(
        rand,
        Array.from({ length: oldSize }, () => `k${nextKey++}`)
      );

      // Build newKeys by shuffling a subset of old and mixing in fresh keys.
      const keptCount = Math.floor(rand() * (oldSize + 1));
      const kept = shuffle(rand, oldKeys).slice(0, keptCount);
      const insertCount = Math.floor(rand() * 6);
      const fresh = Array.from({ length: insertCount }, () => `k${nextKey++}`);
      const newKeys = shuffle(rand, [...kept, ...fresh]);

      const ops = diffChildren(oldKeys, newKeys);
      roundTrips(oldKeys, newKeys);

      // Op-shape sanity: only the three documented kinds, anchors valid.
      for (const op of ops) {
        expect(['insert', 'remove', 'move']).toContain(op.type);
        if (op.beforeKey !== null && op.type !== 'remove') {
          expect(op.key).not.toBe(op.beforeKey);
        }
      }

      // Minimality of moves: never more than matched keys minus LIS size
      // would allow — check against the trivial upper bound n_matched - 1.
      const oldSet = new Set(oldKeys);
      const matched = newKeys.filter((key) => oldSet.has(key)).length;
      const moves = ops.filter((op) => op.type === 'move').length;
      expect(moves).toBeLessThanOrEqual(Math.max(0, matched - 1));
    }
  });

  it('rejects duplicate keys with a clear assertion', () => {
    expect(() => diffChildren(['a', 'a'], ['b'])).toThrow(/duplicate/i);
    expect(() => diffChildren(['a'], ['b', 'b'])).toThrow(/duplicate/i);
    expect(() => diffChildren([1, 2], [3, 3])).toThrow(/duplicate/i);
  });
});
